use std::fs::File;
use std::io::{self, Write};

pub struct RecLog(File);                 // facade owns the descriptor

impl RecLog {
    pub fn open(path: &str) -> io::Result<Self> {
        Ok(RecLog(File::options().append(true).create(true).open(path)?))
    }
    pub fn append(&mut self, line: &str) -> io::Result<()> {
        writeln!(self.0, "{line}")
    }
}                                        // closed exactly once, on drop

