pub struct Sensor(NonNull<sensor_t>);   // owned C handle, never copied

impl Sensor {
    pub fn open(path: &CStr) -> Result<Self, Error> {
        let h = unsafe { sensor_open(path.as_ptr()) };
        NonNull::new(h).map(Sensor).ok_or(Error::OpenFailed)
    }
}

impl Drop for Sensor {
    fn drop(&mut self) { unsafe { sensor_close(self.0.as_ptr()) } }
}
